input.new_string:
.row-label {
  color: var(--text-muted);
  white-space: nowrap;
  flex: 0 0 auto;
  display: inline-flex;
  align-items: center;
  gap: 4px;
}

.info-wrap {
  position: relative;
  display: inline-flex;
}

.info-btn {
  width: 13px;
  height: 13px;
  flex: 0 0 auto;
  border-radius: 50%;
  border: 1px solid var(--text-muted);
  background: transparent;
  color: var(--text-muted);
  font-family: Georgia, "Times New Roman", serif;
  font-style: italic;
  font-size: 9px;
  line-height: 1;
  padding: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
}

.info-btn:hover,
.info-btn:focus-visible {
  color: var(--text);
  border-color: var(--text);
}

.tooltip {
  position: absolute;
  top: 140%;
  left: 0;
  z-index: 20;
  width: 220px;
  max-width: min(240px, calc(100vw - 32px));
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: 6px;
  padding: 8px 10px;
  box-shadow: 0 4px 14px rgba(0, 0, 0, 0.2);
  font-size: 11.5px;
  line-height: 1.4;
  color: var(--text);
  white-space: normal;
}

.tooltip-text {
  margin: 0 0 6px;
}

.tooltip-link {
  color: var(--accent);
  text-decoration: none;
  font-size: 11px;
  font-family: var(--sans);
}

.tooltip-link:hover {
  text-decoration: underline;
}

